def add(a, b):
    return a + b


print(add(2, 3))

def normalize(value):
    return max(0, min(value, 100))


print(normalize(42))

function formatAmount(value) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value);
}
console.log(formatAmount(42.5));

