const values: number[] = [1, 2, 3, 4];
const total = values.reduce((sum, value) => sum + value, 0);
console.log(total);

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}
console.log(clamp(8, 0, 10));
